-- ----------------------------
-- Table structure for wf_approval_record
-- ----------------------------
DROP TABLE IF EXISTS `wf_approval_record`;
CREATE TABLE `wf_approval_record` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '审批记录ID（UUID）',
  `process_instance_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程实例ID',
  `process_definition_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程定义ID',
  `node_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '审批节点ID',
  `node_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批节点名称',
  `approval_targets` json DEFAULT NULL COMMENT '审批目标配置（JSON格式）：[{"id":1,"type":"user","name":"张三"}]',
  `approval_user_ids` json DEFAULT NULL COMMENT '展开后的实际审批用户ID列表（JSON数组）：["1","2","3"]',
  `approval_user_names` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '展开后的实际审批用户姓名（顿号分隔）',
  `approval_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'ANY' COMMENT '审批方式：ANY-或签（任意一人审批）/ALL-会签（所有人审批）',
  `status` tinyint DEFAULT '1' COMMENT '审批状态：1-进行中 2-已通过 3-已驳回',
  `total_count` int DEFAULT '0' COMMENT '总审批人数',
  `approved_count` int DEFAULT '0' COMMENT '已通过审批人数',
  `rejected_count` int DEFAULT '0' COMMENT '已驳回审批人数',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) DEFAULT '0' COMMENT '逻辑删除标识',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='流程审批节点记录表';

-- ----------------------------
-- Records of wf_approval_record
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for wf_cc_record
-- ----------------------------
DROP TABLE IF EXISTS `wf_cc_record`;
CREATE TABLE `wf_cc_record` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '抄送记录ID（UUID）',
  `process_instance_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程实例ID',
  `process_definition_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程定义ID',
  `node_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '抄送节点ID',
  `node_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '抄送节点名称',
  `cc_targets` json DEFAULT NULL COMMENT '抄送目标配置（JSON格式）：[{"id":1,"type":"user","name":"张三"}]',
  `cc_user_ids` json DEFAULT NULL COMMENT '展开后的实际抄送用户ID列表（JSON数组）：[1,2,3]',
  `cc_user_names` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '展开后的实际抄送用户姓名（顿号分隔）',
  `notify_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'SYSTEM' COMMENT '通知方式：SYSTEM/EMAIL/SMS/ALL',
  `require_read` tinyint(1) DEFAULT '0' COMMENT '是否需要确认阅读',
  `cc_time` datetime DEFAULT NULL COMMENT '抄送时间',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) DEFAULT '0' COMMENT '逻辑删除标识',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='流程抄送节点记录表';

-- ----------------------------
-- Records of wf_cc_record
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for wf_history_activity
-- ----------------------------
DROP TABLE IF EXISTS `wf_history_activity`;
CREATE TABLE `wf_history_activity` (
  `id` varchar(64) NOT NULL COMMENT '记录ID',
  `process_instance_id` varchar(64) NOT NULL COMMENT '流程实例ID',
  `node_id` varchar(64) NOT NULL COMMENT '节点ID',
  `node_name` varchar(255) NOT NULL COMMENT '节点名称',
  `node_type` varchar(20) NOT NULL COMMENT '节点类型：START/APPROVAL/CONDITIONAL_BRANCH/END',
  `start_time` datetime NOT NULL COMMENT '节点开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '节点结束时间',
  `duration` bigint DEFAULT NULL COMMENT '耗时(毫秒)',
  `operator` varchar(64) DEFAULT NULL COMMENT '操作人',
  `comment` varchar(512) DEFAULT NULL COMMENT '操作备注',
  PRIMARY KEY (`id`),
  KEY `idx_process_instance` (`process_instance_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='流程活动历史表';

-- ----------------------------
-- Records of wf_history_activity
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for wf_process_definition
-- ----------------------------
DROP TABLE IF EXISTS `wf_process_definition`;
CREATE TABLE `wf_process_definition` (
  `id` varchar(64) NOT NULL COMMENT '流程定义ID',
  `name` varchar(255) NOT NULL COMMENT '流程名称',
  `key` varchar(100) NOT NULL COMMENT '流程标识（用于区分不同版本）',
  `version` int NOT NULL DEFAULT '1' COMMENT '流程版本号',
  `json_def` text NOT NULL COMMENT 'JSON格式的流程定义',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1-激活 0-禁用',
  `description` varchar(512) DEFAULT NULL COMMENT '流程描述',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `business_type` tinyint NOT NULL DEFAULT '1' COMMENT '业务类型：1-系统表单 2-业务表单',
  `business_form_id` varchar(64) DEFAULT NULL COMMENT '业务表单ID（业务表单类型时使用）',
  `business_view` longtext COMMENT '业务视图配置：业务表单时存储formConfig的JSON配置，系统表单时存储视图地址',
  `system_form_key` varchar(100) DEFAULT NULL COMMENT '系统表单标识（系统表单类型时使用）',
  `priority` tinyint DEFAULT '0' COMMENT '流程优先级：0-普通 1-高 2-中 3-低',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_key_version` (`key`,`version`) COMMENT '同标识不同版本唯一'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='流程定义表';

-- ----------------------------
-- Records of wf_process_definition
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for wf_process_definition_version
-- ----------------------------
DROP TABLE IF EXISTS `wf_process_definition_version`;
CREATE TABLE `wf_process_definition_version` (
  `id` varchar(64) NOT NULL COMMENT '版本记录ID',
  `process_def_id` varchar(64) NOT NULL COMMENT '关联流程定义ID',
  `name` varchar(255) NOT NULL COMMENT '流程名称',
  `key` varchar(100) NOT NULL COMMENT '流程标识',
  `version` int NOT NULL COMMENT '流程版本号',
  `json_def` text NOT NULL COMMENT 'JSON格式的流程定义',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1-激活 0-禁用',
  `description` varchar(512) DEFAULT NULL COMMENT '流程描述',
  `business_type` tinyint NOT NULL DEFAULT '1' COMMENT '业务类型：1-系统表单 2-业务表单',
  `business_form_id` varchar(64) DEFAULT NULL COMMENT '业务表单ID（业务表单类型时使用）',
  `business_view` longtext COMMENT '业务视图配置：业务表单时存储formConfig的JSON配置，系统表单时存储视图地址',
  `system_form_key` varchar(100) DEFAULT NULL COMMENT '系统表单标识（系统表单类型时使用）',
  `priority` tinyint DEFAULT '0' COMMENT '流程优先级：0-普通 1-高 2-中 3-低',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_process_def_id` (`process_def_id`),
  KEY `idx_key_version` (`key`,`version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='流程定义版本记录表';

-- ----------------------------
-- Records of wf_process_definition_version
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for wf_process_instance
-- ----------------------------
DROP TABLE IF EXISTS `wf_process_instance`;
CREATE TABLE `wf_process_instance` (
  `id` varchar(64) NOT NULL COMMENT '实例ID',
  `process_def_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '关联流程定义ID',
  `process_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '流程标识',
  `business_key` varchar(64) DEFAULT NULL COMMENT '业务关联ID（如订单ID）',
  `status` tinyint DEFAULT NULL COMMENT '状态：1-运行中 2-已结束 3-已暂停',
  `variables` text COMMENT '流程变量（JSON格式）',
  `current_node_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '当前节点ID',
  `start_user` varchar(64) DEFAULT NULL COMMENT '发起人',
  `start_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `process_def_version_id` varchar(64) DEFAULT NULL COMMENT '关联流程定义版本记录ID',
  PRIMARY KEY (`id`),
  KEY `idx_process_def` (`process_def_id`),
  KEY `idx_business_key` (`business_key`),
  KEY `idx_process_def_version` (`process_def_version_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='流程实例表';

-- ----------------------------
-- Records of wf_process_instance
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for wf_task
-- ----------------------------
DROP TABLE IF EXISTS `wf_task`;
CREATE TABLE `wf_task` (
  `id` varchar(64) NOT NULL COMMENT '任务ID',
  `process_instance_id` varchar(64) NOT NULL COMMENT '关联流程实例ID',
  `node_id` varchar(64) NOT NULL COMMENT '关联节点ID',
  `node_name` varchar(255) NOT NULL COMMENT '节点名称',
  `assignee` varchar(64) NOT NULL COMMENT '处理人',
  `status` tinyint NOT NULL COMMENT '状态：1-待处理 2-已完成 3-已驳回',
  `priority` tinyint DEFAULT '3' COMMENT '优先级：1-高 2-中 3-低',
  `variables` text COMMENT '任务变量（JSON格式）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `complete_time` datetime DEFAULT NULL COMMENT '完成时间',
  `complete_user` varchar(64) DEFAULT NULL COMMENT '完成人',
  `comment` varchar(512) DEFAULT NULL COMMENT '处理意见',
  `process_def_version_id` varchar(64) DEFAULT NULL COMMENT '关联流程定义版本记录ID',
  PRIMARY KEY (`id`),
  KEY `idx_process_instance` (`process_instance_id`),
  KEY `idx_assignee_status` (`assignee`,`status`) COMMENT '查询个人待办任务',
  KEY `idx_process_def_version` (`process_def_version_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='任务表';

-- ----------------------------
-- Records of wf_task
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for zapi_flow_test_order
-- ----------------------------
DROP TABLE IF EXISTS `zapi_flow_test_order`;
CREATE TABLE `zapi_flow_test_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '订单ID，主键，自增长',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单号，订单的唯一标识，例如：ORD20241226001',
  `order_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单名称，订单的显示名称，例如：测试订单001',
  `order_count` int NOT NULL COMMENT '订单数量，订单包含的商品数量',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`) COMMENT '订单号唯一索引',
  KEY `idx_order_name` (`order_name`) COMMENT '订单名称索引，用于模糊查询'
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='流程测试订单表';

-- ----------------------------
-- Records of zapi_flow_test_order
-- ----------------------------
BEGIN;
COMMIT;

SET FOREIGN_KEY_CHECKS = 1;
